from typing import Dict, List

from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info, log_debug
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import UnsupportedState, UnexpectedState
from taf.rfrl.procedures.resources.python.bts.utils.timer import wait_for, wait_for_not


class BtsComponent:
    """ Represents generic component, physical or logical, connected to or configured on BTS. """

    _MISSING_IMPLEMENTATION_ERROR_MSG = '{} class has missing implementation of {}'
    _IS_IN_STATE_MISSING_ARGS_ERROR_MSG = 'Neither state nor statuses where provided to check {} state but at least one must be used'
    _IS_IN_STATE_TOO_MANY_ARGS_ERROR_MSG = 'Both state and statuses where provided to check {} state but only one can be used'
    _UNSUPPORTED_STATE_ERROR_MSG = 'Unsupported state {} was provided to check {} state'

    def __init__(self, name):
        """
        :param name: name of this component; i.e. 'RMOD-1' or 'NRCELL-1'
        """
        self._name = name

    @property
    def name(self) -> str:
        """ Returns name of this BTS component, unique for this BTS; i.e. 'RMOD-1' or 'NRCELL-1' """
        return self._name

    @pretty_log
    def is_in_state(self, state: str = None, timeout: int = 0, silent: bool = False, **statuses: str) -> bool:
        """
        Informs whether BTS component can reach given state.
        Either entire state or individual statuses need to be provided. Cannot provide both at the same time.
        :param state: name of expected, predefined state which then will be translated into collection of
                      individual statuses and their expected values used during state verification;
                      i.e. state='blocked';
                      defaults to None (state will not be used but statuses need to be provided)
        :param timeout: time (in seconds) in which expected state should be reached;
                        defaults to 0 (BTS component should be in expected state now)
        :param silent: determines whether non-error logs should appear on console (False) or not (True);
                       defaults to False (non-error logs visible on console)
        :param statuses: keyword arguments representing custom statuses and their expected values which should be used
                         during state verification;
                         i.e. procedural_status='configured';
                         if statuses are not provided then state needs to be provided
        :return: True if all statuses can reach their expected values, False otherwise
        :raises UnsupportedState: if both state and statuses are provided at the same time or
                                  neither of them is provided
        """
        return self._is_in_state(state, timeout, silent, **statuses)

    @pretty_log
    def is_not_in_state(self, state: str = None, timeout: int = 0, silent: bool = False, **statuses: str) -> bool:
        """
        Informs whether BTS component can reach any state other than given one.
        Either entire state or individual statuses need to be provided. Cannot provide both at the same time.
        :param state: name of predefined state which then will be translated into collection of
                      individual statuses and their values used during state verification;
                      i.e. state='blocked';
                      defaults to None (state will not be used but statuses need to be provided)
        :param timeout: time (in seconds) in which any state other than given one should be reached;
                        defaults to 0 (BTS component should not be in given state now)
        :param silent: determines whether non-error logs should appear on console (False) or not (True);
                       defaults to False (non-error logs visible on console)
        :param statuses: keyword arguments representing custom statuses and their values which should be used
                         during state verification;
                         it will be checked whether ALL statuses can reach values other than provided;
                         i.e. procedural_status='configured';
                         if statuses are not provided then state needs to be provided
        :return: True if all statuses can reach any values other than given one, False otherwise
        :raises UnsupportedState: if both state and statuses are provided at the same time or
                                  neither of them is provided
        """
        return self._is_not_in_state(state, timeout, silent, **statuses)

    @pretty_log
    def check_state(self, state: str = None, timeout: int = 0, silent: bool = False, **statuses: str):
        """
        Checks whether BTS component can reach given state.
        Either entire state or individual statuses need to be provided. Cannot provide both at the same time.
        :param state: name of expected, predefined state which then will be translated into collection of
                      individual statuses and their expected values used during state verification;
                      i.e. state='blocked';
                      defaults to None (state will not be used but statuses need to be provided)
        :param timeout: time (in seconds) in which expected state should be reached;
                        defaults to 0 (BTS component should be in expected state now)
        :param silent: determines whether non-error logs should appear on console (False) or not (True);
                       defaults to False (non-error logs visible on console)
        :param statuses: keyword arguments representing custom statuses and their expected values which should be used
                         during state verification;
                         i.e. procedural_status='configured';
                         if statuses are not provided then state needs to be provided
        :raises UnexpectedState: if given state cannot be reached
        :raises UnsupportedState: if both state and statuses are provided at the same time or
                                  neither of them is provided
        """
        self._check_state(state, timeout, silent, **statuses)

    @pretty_log
    def check_not_in_state(self, state: str = None, timeout: int = 0, silent: bool = False, **statuses: str):
        """
        Checks whether BTS component can reach any state other than given one.
        Either entire state or individual statuses need to be provided. Cannot provide both at the same time.
        :param state: name of predefined state which then will be translated into collection of
                      individual statuses and their values used during state verification;
                      i.e. state='blocked';
                      defaults to None (state will not be used but statuses need to be provided)
        :param timeout: time (in seconds) in which any state other than given one should be reached;
                        defaults to 0 (BTS component should not be in given state now)
        :param silent: determines whether non-error logs should appear on console (False) or not (True);
                       defaults to False (non-error logs visible on console)
        :param statuses: keyword arguments representing custom statuses and their values which should be used
                         during state verification;
                         it will be checked whether ALL statuses can reach values other than provided;
                         i.e. procedural_status='configured';
                         if statuses are not provided then state needs to be provided
        :raises UnexpectedState: if state other than given one cannot be reached
        :raises UnsupportedState: if both state and statuses are provided at the same time or
                                  neither of them is provided
        """
        self._check_not_in_state(state, timeout, silent, **statuses)

    def _is_in_state(self, state: str = None, timeout: int = 0, silent: bool = False, **statuses: str) -> bool:
        self._check_state_arguments(state, statuses)
        expected_statuses = self._get_expected_statuses(state) if state else statuses
        interval = 5
        self._log_details_of_expected_state(timeout, interval, expected_statuses, silent)

        expected_state_reached = wait_for(expected_value=expected_statuses,
                                          abort_if=None,
                                          timeout=timeout,
                                          raise_exc=False,
                                          callback=self._get_current_statuses,
                                          statuses_names=list(expected_statuses.keys()))
        if expected_state_reached:
            log_debug(f'State of {self._name} is: \n{expected_statuses}')
            return True
        else:
            log_debug(f'State of {self._name} is not: \n{expected_statuses}')
            return False

    def _is_not_in_state(self, state: str = None, timeout: int = 0, silent: bool = False, **statuses: str) -> bool:
        self._check_state_arguments(state, statuses)
        statuses = self._get_expected_statuses(state) if state else statuses
        interval = 5
        self._log_details_of_not_expected_state(timeout, interval, statuses, silent)

        other_state_reached = wait_for_not(value=statuses,
                                           abort_if=None,
                                           timeout=timeout,
                                           raise_exc=False,
                                           callback=self._get_current_statuses,
                                           statuses_names=list(statuses.keys()))

        if other_state_reached:
            log_debug(f'State of {self._name} is not: \n{statuses}')
            return True
        else:
            log_debug(f'State of {self._name} is: \n{statuses}')
            return False

    def _check_state(self, state: str = None, timeout: int = 0, silent: bool = False, **statuses: str):
        state_as_expected = self._is_in_state(state, timeout, silent, **statuses)

        if not state_as_expected:
            raise UnexpectedState(f'State of {self._name} is not as expected')

    def _check_not_in_state(self, state: str = None, timeout: int = 0, silent: bool = False, **statuses: str):
        state_as_expected = self._is_not_in_state(state, timeout, silent, **statuses)

        if not state_as_expected:
            raise UnexpectedState(f'State of {self._name} is not as expected')

    def _check_state_arguments(self, state, statuses):
        if state is None and not statuses:
            raise UnsupportedState(self._IS_IN_STATE_MISSING_ARGS_ERROR_MSG.format(self._name))

        if state is not None and statuses:
            raise UnsupportedState(self._IS_IN_STATE_TOO_MANY_ARGS_ERROR_MSG.format(self._name))

    def _get_expected_statuses(self, state: str) -> Dict[str, str]:
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                                                '_get_expected_statuses'))

    def _log_details_of_expected_state(self, timeout, interval, expected_statuses, silent=False):
        timeout_msg = f" before {timeout}s timeout, every {interval}s" if timeout else ""
        log_info(f'Checking if state of {self._name} is as expected{timeout_msg}', to_console=not silent)
        log_debug(f'{self._name} expected state: \n{expected_statuses}')

    def _log_details_of_not_expected_state(self, timeout, interval, not_expected_statuses, silent=False):
        timeout_msg = f" before {timeout}s timeout, every {interval}s" if timeout else ""
        log_info(f'Checking if state of {self._name} is as expected{timeout_msg}', to_console=not silent)
        log_debug(f'{self._name} expected state: not \n{not_expected_statuses}')

    def _get_current_statuses(self, statuses_names: List[str]) -> Dict[str, str]:
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                                                '_get_current_statuses'))
